// lib
using MessagePack;

namespace Lib
{
    [MessagePackObject]
    public class BaseMessage
    {
        // Comes to the app as metadata: no DeclaringSyntaxReferences there.
        [Key(0)]
        public int BaseValue { get; set; }
    }
}

// app
using MessagePack;

namespace App
{
    // Members are enumerated derived-first, so DerivedValue takes key 0,
    // then the metadata member Lib.BaseMessage.BaseValue arrives with the same key 0.
    [MessagePackObject]
    public class DerivedMessage : Lib.BaseMessage
    {
        [Key(0)]
        public int DerivedValue { get; set; }
    }

    public static class Program
    {
        public static void Main()
        {
            var bytes = MessagePackSerializer.Serialize(new DerivedMessage { BaseValue = 1, DerivedValue = 2 });
            System.Console.WriteLine(bytes.Length);
        }
    }
}

// lib
using MessagePack;

namespace Lib
{
    [MessagePackObject]
    public class Base
    {
        // String key "a" declared in the referenced assembly (metadata only, no syntax reference in the app compilation).
        [Key("a")]
        public int A { get; set; }
    }
}

// app
using MessagePack;
using Lib;

namespace App
{
    // Derived members are visited first, so "a" is already in stringMembers when the
    // metadata-declared Base.A is reached: the duplicate is reported as MsgPack005 with no location.
    // Old: stringMembers.Add then throws ArgumentException (analyzer/generator crash).
    // New: only MsgPack005 is reported.
    [MessagePackObject]
    public class Derived : Base
    {
        [Key("a")]
        public int B { get; set; }
    }

    public static class Program
    {
        public static void Main()
        {
            var bytes = MessagePackSerializer.Serialize(new Derived { A = 1, B = 2 });
            System.Console.WriteLine(bytes.Length);
        }
    }
}
